#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int dario_wins = 0;
    int xerxes_wins = 0;

    for (int i = 0; i < n; i++) {
        int d, x;
        scanf("%d %d", &d, &x);

        if ((d + 1) % 5 == x || (d + 2) % 5 == x) {
            dario_wins++;
        } else {
            xerxes_wins++;
        }
    }

    if (dario_wins > xerxes_wins) {
        printf("dario\n");
    } else {
        printf("xerxes\n");
    }

    return 0;
}
```

